/* Source, projection, application snapshot and server authentication are distinct facts. */
const configObjects=infraReadableHTML(
 '<div class="mechanism-core" id="config-effective-versions">'+knowledgeSubhead('先分对象：配置值、凭据、身份与版本')+
 para('配置决定程序怎样工作，例如连接池上限和等待超时；凭据用来证明调用者持有某种身份，例如令牌或密钥；授权再判断这个身份能对哪个资源做什么。把三者都叫“配置”，容易只验文件内容，却漏掉服务端权限与有效期。ConfigMap适合普通配置，Secret承载需限制分发的敏感值；对象类型本身不能代替完整的访问控制。',
 '一次更新至少有四个观察点：API保存的源版本、容器路径可见的文件版本、进程内存的生效快照、服务端接受的认证版本。它们可以同时不同。源已经是v2，某节点文件仍v1；文件变v2，进程解析失败仍用v1；进程加载了v2，连接池还在复用v1建立的会话。每个现象都有可能，不能用一条“发布成功”日志代替。')+
 table(['对象或证据','回答什么','不能单独证明什么'],[
 ['API中的源对象','期望内容保存了吗','所有Pod已拿到、进程已使用'],
 ['目标容器路径','此刻重新打开能看到什么','旧文件描述符、内存快照与所有副本状态'],
 ['应用报告的生效代际','成功校验并发布了哪份快照','下游已接受凭据、真实请求质量达标'],
 ['下游新认证与效果','指定凭据及范围是否有效','旧凭据或既有会话已退出']])+
 para('应用代际是我们为候选和生效顺序定义的整数，不等于Kubernetes的resourceVersion。后者是API并发与观察使用的不透明版本值，不应转成整数当作业务发布时间，更不能跨对象比较大小。发布记录还应关联镜像摘要、配置内容摘要、引用的凭据版本和数据契约；不记录秘密原文。')+'</div>');

const configPropagation=infraReadableHTML(
 knowledgeSubhead('注入方式决定更新路径，重新打开才可能看到新文件')+
 table(['注入路径','已有进程怎样变化','应验证什么'],[
 ['env / envFrom','对象更新不会改已有进程环境；通常更新Pod模板并滚动替换','新Pod引用、启动时间和生效代际'],
 ['普通ConfigMap/Secret投射卷','内容可最终传播；延迟受节点同步与检测缓存方式影响','各副本路径版本、重读与加载结果'],
 ['subPath挂载','不能依靠普通投射卷的自动更新','重建或另选更新方式，不无限等待'],
 ['外部配置/身份客户端','依客户端缓存、轮询/订阅、续期与失败策略','刷新时刻、候选校验、到期及退避']])+
 para('文件路径是一个查找入口，文件描述符（FD）是进程已经打开的对象。路径替换成新版本后，旧FD可能仍指向旧内容；长期保留的解析对象更不会自动变化。应用应按实际投射机制重新打开完整配置并校验，而不是仅收到“文件发生变化”的通知就宣布成功。文件监视若绑在被替换的对象上，也可能需要重新建立观察；事件还可能合并或丢失，所以通知是触发重新核对的信号。',
 '本地实验让旧、新两个版本目录一直保留，以便清楚观察FD和路径的区别。真实Kubernetes投射、符号链接结构和旧目录清理须按版本实现核对，不能把实验里的目录寿命当作平台保证。已有进程环境也用真实子进程验证：父方启动模板从4改6，旧子进程仍4，新启动子进程才6。')+
 code('只读核对 · 在自己的测试集群替换对象名，不输出Secret正文','SHELL',
 'kubectl -n apps get deployment reports -o yaml\nkubectl -n apps get pods -l app=reports -o wide\nkubectl -n apps describe pod <pod-name>\n# 对照容器名、envFrom/volume/subPath引用、Pod创建时间和应用的非敏感生效代际'));

const configSnapshot=infraReadableHTML(
 knowledgeSubhead('把多字段作为一份快照加载，避免拼出从未发布的组合')+
 para('v1规定连接池上限4、等待100ms；v2规定6、50ms。若程序先从当前路径读pool=4，路径切换后再读timeout_ms=50，就拼出了4/50。单次路径替换即使完成得很整齐，也不意味着两次独立open属于同一个版本。解决目标是“这次请求使用的字段同属一个经过校验的配置”，而不只是“每个文件都能读出来”。')+
 figure('v25-config-snapshot','实际文件实验：两次打开能混合版本；完整JSON、不可变对象和一次发布引用使每个请求持有一致快照。')+
 para('可将相关字段放入一份完整JSON，从一次打开的文件读完，再解析成候选；或先解析版本目录，再从同一保留版本读取全部字段。若使用清单与摘要，需要核验所有文件属于声明集合，并对缺失或摘要不符重试/拒绝。不能一边读字段一边修改全局生效对象。',
 '校验顺序可以是：结构和必需字段→精确类型与单位→范围→跨字段关系→全局资源预算→候选代际。全部通过后构造不可变对象，再用运行时支持的同步方式发布引用。Python示例只演示单线程切换；真实多线程/多进程应使用对应的锁、版本发布或广播协议，不能从一个语言的引用行为推导所有平台都安全。',
 '请求开始时捕获一次生效引用，之后沿用它；新请求从切换点捕获新引用。旧连接池等有资源对象要定义排空和释放，不能仅将数字改小就假定连接立即消失。校验失败保留最后已知可用快照，同时暴露候选代际、失败类别和上次成功时间。缺少这些观测，保留旧值可能看似稳定，实际已长期无法更新。'));

const configBudget=infraReadableHTML(
 knowledgeSubhead('字段合法还不够：副本乘连接池，会放大全局资源')+
 para('实验设4个实例共享32个应用连接预算。单实例pool=6时最大24，候选pool=9虽然在单字段1..12范围内，合计36却超预算，因此拒绝。一般计算应是所有实例与滚动期间新旧副本的上限之和，再加其他客户端与维护余量。不能只拿稳定副本数乘新值：滚动更新中额外Pod也可能先建连接。')+
 knowledgeFormula('先列总预算','应用最大连接 = Σ(各代际副本数 × 对应单副本池上限)','还要加其他客户端与预留；连接上限可行，不证明数据库吞吐或事务延迟可行。')+
 para('超时也要说明是连接建立、获取池连接、单次RPC还是整个请求截止时间。外层剩余80ms，内层等待100ms再重试，动作可能到用户已放弃后才完成。更新不能把单位从ms误读成秒，也不能让多层独立重试把数据库压力成倍放大。把配置变化与真实池等待、在途请求和下游完成率同时核对。',
 '回退时回到旧业务值，但发布新的代际。示例从v2的6/50回到4/100，代际用7；迟到的v1候选仍被拒绝。新代际用于阻止过期通知覆盖当前决策，业务值则可以合法回退。若旧镜像无法解析新配置或凭据已经撤销，单纯回退镜像并不能恢复系统，需要提前验证兼容窗口。'));

const secretBoundary=infraReadableHTML(
 knowledgeSubhead('Secret保护的是分发链，base64不提供保密性')+
 para('Secret.data中的base64是字节编码，可直接解码；传输TLS、etcd等静态存储加密、API权限、节点/容器访问与日志脱敏分别保护不同位置。应核对实际集群的静态加密配置与密钥管理，不能因为用了Secret对象便声称存储已经加密。',
 '授权还要看间接路径：能在同一命名空间创建任意Pod的主体，可能通过挂载接触Secret，即使没有直接get Secret的权限。限制谁能创建什么工作负载、使用什么服务账号、挂载哪些对象，以及哪些容器真正需要凭据。只负责指标的旁路容器不应顺便拿到文档库密钥。',
 '工作负载身份将运行实体与服务身份关联，短期令牌还涉及受众、权限、到期和续期。身份可验证不等于有权读取所有租户；认证、业务授权和效果验收仍须分别执行。不要把长期凭据写进镜像、前端静态文件、Git历史或实验输出；诊断只记非敏感版本和认证结果。本章的公开实验常量没有生产权限。')+
 linkTo('iam-security','复习身份、受众、资源范围与执行端授权'));

const secretRotation=infraReadableHTML(
 knowledgeSubhead('先让新凭据可用，再迁移客户端，最后验证旧能力退出')+
 para('若服务端支持两个凭据同时有效，正常轮换是：先启用v2并保留v1→用新连接验证v2的身份和资源范围→发布引用v2的候选→逐副本确认加载与新认证→等待旧客户端按约定退出→撤销v1→用受控旧凭据验证新认证失败。还要核对新流量质量，而不是只看版本字符串。')+
 figure('v25-credential-overlap','本机HTTP实测的轮换顺序及反例。撤销签发凭据与处理已建立会话，在本夹具中是两项独立动作。')+
 para('错误顺序先撤v1，而客户端还缓存v1，实验立即得到401。相反，永远保持两者有效也没有完成退出。窗口应由滚动速度、缓存刷新、连接与令牌寿命决定，并设负责人、截止时间和可观测退出条件。若服务只允许一个凭据，要使用受控维护或可协调切换的机制，并量化中断；若凭据已泄露，可能需要立即撤销并接受短时错误，不能照搬例行兼容窗口。',
 '新认证失败、旧会话失败和旧授权失效不是同一个事件。服务可能在每次请求重新校验，也可能在建连时确定身份，或签发独立会话。本实验选择独立会话：v1密钥撤销后新认证401，但先前会话仍200；显式撤会话后才401。真实平台要按协议测试，不能把这组状态推广。业务回滚应使用当前合法凭据，不能重新启用已泄露的旧密钥来恢复旧代码。'));

const configPractice=infraReadableHTML(
 knowledgeSubhead('实战一：真实文件、候选校验与进程环境')+cmeLab('config_snapshots.py')+
 knowledgeCheck('把实例数从4改6，pool=6还能接受吗？','原32连接预算下，6×6=36，应拒绝；若代码仍只乘4，就是校验使用了过期副本假设。再检查滚动额外副本和其他客户端。')+
 knowledgeSubhead('实战二：真实HTTP的新旧凭据与会话')+cmeLab('credential_rotation.py')+
 para('到自己的测试集群，按对象保存、文件可见、候选加载、生效切换、新认证、撤销验证六个时间点留证；同时覆盖env、普通投射和subPath。练习包只验证本地机制，平台投射与真实身份服务的时延、撤销和故障需要另测。不要将真实Secret打印进排查记录。')+
 knowledgeCheck('应用说已加载v2，为什么还不能宣布轮换完成？','可能没有以v2建立新认证，仍复用v1会话；其他副本也可能未切换。确认服务端按预期接受v2、旧客户端退出、v1新认证被拒，按协议处理旧会话，并验证真实请求质量。'));

{
 const a=articles.find(a=>a.id==='config-secrets');
 a.sections=[['对象与版本：期望、文件、内存和认证',configObjects],['传播路径：环境变量、投射与subPath',configPropagation],['一致快照：完整读取、校验和请求切换',configSnapshot],['全局约束：连接预算、截止时间与回退',configBudget],['Secret与身份：分发、存储和执行权限',secretBoundary],['凭据轮换：兼容窗口、撤销与旧会话',secretRotation],['实战与变化题：文件、进程和真实HTTP',configPractice]];
 a.refs=nitRefs([...a.refs,'v25Config','v25Secret']);a.minutes=50;a.updated='2026.11.05';
 a.intro='沿源对象、容器文件、进程快照和服务端认证四个观察点，解释更新为何尚未生效；再用完整快照、资源预算和兼容窗口完成切换。';
 a.objectives=['分清环境变量、投射卷与subPath的更新路径','实现完整候选校验和保留最后可用快照','验证新认证、旧凭据撤销与既有会话的不同边界'];
 a.check=['能解释源对象、文件和内存版本为何不同','能复现未发布的混合字段并说明修复条件','能按真实协议验证凭据与会话退出'];
}
cloudKnowledgeExplanations.configuration=configObjects+configPropagation+configSnapshot+configBudget+secretBoundary+secretRotation;
cloudKnowledgeDomain('native').refs=nitRefs([...cloudKnowledgeDomain('native').refs,'v25Config','v25Secret']);
const configLabsBeforeCME=cloudFieldLabs;
cloudFieldLabs=id=>(id==='native'?'<h3>配置与轮换：路径、快照和真实认证</h3>'+cmeLab('config_snapshots.py',false)+cmeLab('credential_rotation.py',false)+linkTo('config-secrets','阅读配置更新与凭据轮换的完整机制'):'')+configLabsBeforeCME(id);
